INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70474, 0, 0, '$n has been |cFFFF0000|Hspell:141407|h[Frozen Solid]|h|r. Break $ghim:her; free!', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70544, 0, 0, 'You may have stopped the storm, but you cannot stop the will of Zandalar! You will DIE, here... ALL OF YOU!', 14, 0, 100, 0, 0, 37173, ''),
(70544, 1, 0, 'Trolls of the world will unite against you!', 14, 0, 100, 0, 0, 37174, ''),
(70544, 2, 0, 'We control the sand, the seas, the winds...', 14, 0, 100, 0, 0, 37175, ''),
(70544, 3, 0, 'We will bury you in your mountain!', 14, 0, 100, 0, 0, 37176, ''),
(70544, 4, 0, 'There... will be more! Zandalar... will never fall...', 14, 0, 100, 0, 0, 37172, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70602, 0, 0, 'Oh ho ho ho ho! By my beard, I thought I was done for! Oh, thank ye. Thank ye!', 14, 0, 100, 4, 0, 37296, ''),
(70602, 1, 0, 'Oh... right. Now: Did the human king send ye? Oh, his spies are all dead... and most of us are, too.', 12, 0, 100, 6, 0, 37297, ''),
(70602, 2, 0, 'I saw \'em draggin\' Boldbrew, kickin\' and bitin\', towards some hut south o\' here. Now if ye hurry, ye can help her, and she might know more.', 12, 0, 100, 25, 0, 0, ''),
(70602, 3, 0, 'BUT STAY AWAY FROM THE  BIG VILLAGE! There\'s dozens o\' mad ice trolls in there! Oh, that Zandalari priest has \'em whipped up into a great frenzy.', 12, 0, 100, 5, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70744, 0, 0, 'Oh, that was a CLOSE one, thank ye!', 14, 0, 100, 71, 0, 37292, ''),
(70744, 1, 0, 'There\'s only a few of us left; the ones they don\'t eat, they butcher at some big altar.', 12, 0, 100, 396, 0, 37293, ''),
(70744, 2, 0, 'It\'s just northwest o\' here; if ye hurry, ye might be able ta save some! Sorry I don\'t know anythin\' more...', 12, 0, 100, 397, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70745, 0, 0, 'Filthy monsters! I owe ye me life.', 14, 0, 100, 4, 0, 37294, ''),
(70745, 1, 0, 'Listen: The storm. We figured out what\'s makin\' it. That sneaky Zandalari has these ice trolls makin\' blood sacrifices ta elemental spirits.', 12, 0, 100, 1, 0, 37295, ''),
(70745, 2, 0, 'There\'s a cave, north o\' here, across a bridge. If ye can slay the elemental within, the storm ought ta stop.', 12, 0, 100, 25, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70799, 0, 0, 'This is where my agents tracked the Zandalari.', 12, 0, 100, 25, 0, 37328, ''),
(70799, 1, 0, 'I can only imagine what foul business the Zandalari have with them...', 12, 0, 100, 1, 0, 37329, ''),
(70799, 2, 0, 'Yes. This weather is not natural.', 12, 0, 100, 1, 0, 37330, ''),
(70799, 3, 0, 'My champions will go. They will see what can be done, and rescue who they can.', 12, 0, 100, 1, 0, 37331, ''),
(70799, 4, 0, 'It is heartening to see you here, Moira. You have my thanks.', 12, 0, 100, 2, 0, 37332, ''),
(70799, 5, 0, 'Hrmmm. Fare well, Queen Regent.', 12, 0, 100, 66, 0, 37333, ''),
(70799, 6, 0, 'Well fought. I see the Dark Irons are as formidable as ever.', 12, 0, 100, 1, 0, 37334, ''),
(70799, 7, 0, 'Hah! For that, I\'m glad. The Bronzebeards and Wildhammers will regret not having been here to share in your glory.', 12, 0, 100, 1, 0, 37335, ''),
(70799, 8, 0, 'Well, you\'ve done just that. Come; let us return to Ironforge, and announce your victory to the Council.', 12, 0, 100, 1, 0, 37336, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70801, 0, 0, 'The nearest is just ahead. If ye can save him, he may know a thing or two.', 12, 0, 100, 0, 0, 37263, ''),
(70801, 1, 0, 'We\'ll cover ye from the brush: Point out a target, and we\'ll open fire.', 12, 0, 100, 396, 0, 0, '');
