INSERT INTO `instance_template` (`map`, `parent`, `script`, `allowMount`) VALUES (1131, 870, 'instance_secrets_of_ragefire', 1);
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES (142307, 'spell_ragefire_ruined_earth_selector');
INSERT INTO `areatrigger_scripts` (`entry`, `ScriptName`) VALUES (9078, 'AreaTrigger_at_ragefire_sealed_gate');
INSERT INTO `areatrigger_scripts` (`entry`, `ScriptName`) VALUES (9091, 'AreaTrigger_at_ragefire_sealed_gate_items');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70605, 0, 0, 'Newt, get that door open.', 12, 0, 100, 0, 0, 0, ''),
(70605, 1, 0, 'Grit, Ticker and Volt, you three back her up.', 12, 0, 100, 0, 0, 0, ''),
(70605, 2, 0, 'Recruit $p, you\'re with me.', 12, 0, 100, 0, 0, 0, ''),
(70605, 3, 0, 'We\'ve tracked the recent disappearances in Durotar to this abandoned section of Ragefire.', 12, 0, 100, 0, 0, 0, ''),
(70605, 4, 0, 'It\'s our job to find out who\'s behind these abductions and put a stop to them.', 12, 0, 100, 0, 0, 0, ''),
(70605, 5, 0, 'Stay close.', 12, 0, 100, 0, 0, 0, ''),
(70605, 6, 0, 'Newt, we need this door open now.', 12, 0, 100, 0, 0, 0, ''),
(70605, 7, 0, 'Move! Move! Move!', 14, 0, 100, 0, 0, 0, ''),
(70605, 8, 0, 'What the...', 14, 0, 100, 0, 0, 0, ''),
(70605, 9, 0, 'Gob Squad, defend yourselves!', 14, 0, 100, 0, 0, 0, ''),
(70605, 10, 0, 'We aren\'t your enemy, Xorenth!', 14, 0, 100, 0, 0, 0, ''),
(70605, 11, 0, 'Lesser? We\'ll show you who\'s lesser!', 14, 0, 100, 0, 0, 0, ''),
(70605, 12, 0, 'This is bad.', 12, 0, 100, 0, 0, 0, ''),
(70605, 13, 0, 'All of you fan out and search the chamber. If Garrosh is behind this, we\'re going to need proof.', 12, 0, 100, 0, 0, 0, ''),
(70605, 14, 0, 'Quickly, $p! We need you over here!', 14, 0, 100, 0, 0, 0, ''),
(70605, 15, 0, 'Can you open this, Ticker?', 12, 0, 100, 0, 0, 0, ''),
(70605, 16, 0, 'A mantid bomb?! Are you sure that won\'t bring down the whole cavern?', 12, 0, 100, 0, 0, 0, ''),
(70605, 17, 0, 'I don\'t care what it\'s for! Is it going to get this door open?', 12, 0, 100, 0, 0, 0, ''),
(70605, 18, 0, 'That door didn\'t even budge...', 12, 0, 100, 0, 0, 0, ''),
(70605, 19, 0, 'Grit, setup the emergency teleporter! We need to report this to Vol\'jin immediately.', 12, 0, 100, 0, 0, 0, ''),
(70605, 20, 0, 'Recruits, you\'re the only ones left that can fight!', 14, 0, 100, 0, 0, 0, ''),
(70605, 21, 0, 'Defend us until the teleporter is ready!', 14, 0, 100, 0, 0, 0, ''),
(70605, 22, 0, 'Everyone out before more of them show up!', 14, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70683, 0, 0, 'Intruders! Stop them!', 14, 0, 100, 0, 0, 0, ''),
(70683, 1, 0, 'Weaklings!', 14, 0, 100, 0, 0, 38177, ''),
(70683, 2, 0, 'Seal the gate, and inform the overseer immediately.', 14, 0, 100, 0, 0, 0, ''),
(70683, 3, 0, 'All lesser races are enemies of the true Horde!', 14, 0, 100, 0, 0, 0, ''),
(70683, 4, 0, '|TInterface\\Icons\\ability_deathknight_remorselesswinters:20|t%s summons a |cFFF00000|Hspell:142320|h[Glacial Freeze Totem]|h|r!', 41, 0, 100, 0, 0, 0, ''),
(70683, 5, 0, '|TInterface\\Icons\\spell_fire_windsofwoe:20|t%s begins to cast |cFFF00000|Hspell:142306|h[Ruined Earth]|h|r!', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(71030, 0, 0, 'Proto-Drake Whelps hatch from the nearby eggs!', 41, 0, 100, 0, 0, 0, ''),
(71030, 1, 0, 'Embercores wake from the lava!', 41, 0, 100, 0, 0, 0, ''),
(71030, 2, 0, 'You will never escape these caverns!', 14, 0, 100, 0, 0, 0, ''),
(71030, 3, 0, 'The true Horde, the pure Horde, cannot be stopped!', 14, 0, 100, 0, 0, 0, ''),
(71030, 4, 0, 'Destroy them! FOR THE HORDE!', 14, 0, 100, 0, 0, 0, ''),
(71030, 5, 0, '|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t Bonus Objective Started: Defeat all enemies before time runs out!', 41, 0, 100, 0, 0, 0, ''),
(71030, 6, 0, 'Fools! The true Horde cannot be stopped by the likes of you.', 14, 0, 100, 0, 0, 0, '');
