INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70824, 0, 0, 'Fiery Anger is about to |cFFFF2222|Hspell:141456|h[Detonate]|h|r!', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70956, 0, 0, 'Thank the laws of physics you\'re here!', 12, 0, 100, 5, 0, 37164, ''),
(70956, 1, 0, 'We found somethin\' down there, somethin\' HUGE, and all of a sudden the rocks started fightin\' back and everyone went crazy. Bad business!', 12, 0, 100, 0, 0, 37165, ''),
(70956, 2, 0, 'Please, just make it all stop!', 12, 0, 100, 20, 0, 37166, ''),
(70956, 3, 0, 'Just what in the name of all that is unholy was that thing?', 12, 0, 100, 6, 0, 37158, ''),
(70956, 4, 0, 'Oh don\'t you worry none, I don\'t think anyone wants to touch that thing again.  I\'ll collect our money and we are outta here.', 12, 0, 100, 1, 0, 37159, ''),
(70956, 5, 0, 'Hey hey, what is this, huh?  This is barely a fifth of the promised payment!', 12, 0, 100, 5, 0, 37160, ''),
(70956, 6, 0, 'Naw naw naw, see there\'s a contract.  Payment in full is req-', 12, 0, 100, 274, 0, 37161, ''),
(70956, 7, 0, 'Yeah, we\'ll see who\'s got Garrosh\'s back when it counts.', 12, 0, 100, 1, 0, 37162, ''),
(70956, 8, 0, 'Oh yeah, hey no nothing your, uh, your hugeness.  Uh, for the Horde, and all that...  Bye!', 12, 0, 100, 1, 0, 37163, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(70959, 0, 0, 'Minions, destroy these insects!', 14, 0, 100, 0, 0, 0, ''),
(70959, 1, 0, '|cFFFF0000|Hspell:141387|h[Urtharges\' Shield]|h|r has been broken!', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(71123, 0, 0, 'My blood hungers.', 14, 0, 100, 0, 0, 37142, ''),
(71123, 1, 0, 'Your class cooldowns have been reset!', 41, 0, 100, 0, 0, 0, ''),
(71123, 2, 0, 'I only sleep.', 14, 0, 100, 0, 0, 37143, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(71177, 0, 0, 'Step aside goblin.  This artifact is exactly what the warchief hoped to find here.  I am taking it under Kor\'kron protection.', 12, 0, 100, 5, 0, 37182, ''),
(71177, 1, 0, 'You are paid for all workers present, foreman.  The warchief does not compensate the dead.', 12, 0, 100, 1, 0, 37183, ''),
(71177, 2, 0, 'THIS.  This is what has diluted the vitality of our precious Horde!', 12, 0, 100, 0, 0, 37184, ''),
(71177, 3, 0, 'The warchief graciously permits the families of the dead to live in his city.  To die in the service of the Horde should be a great honor, but you see it as another opportunity to line your filthy pockets!', 12, 0, 100, 1, 0, 37185, ''),
(71177, 4, 0, 'Your kind DISGUSTS me.  Small.  Weak.  Honorless as thieves.  Be thankful the warchief still tolerates your presence at all.', 12, 0, 100, 5, 0, 37186, ''),
(71177, 5, 0, 'What was that, goblin?', 12, 0, 100, 547, 0, 37187, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(71358, 0, 0, 'It\'s all clear then?', 12, 0, 100, 0, 0, 0, ''),
(71358, 1, 0, 'No time to waste... let\'s blow this wall to pieces!', 12, 0, 100, 0, 0, 0, ''),
(71358, 2, 0, 'That was some explosion!  Let\'s check it out.', 12, 0, 100, 0, 0, 0, ''),
(71358, 3, 0, 'It looks like some sort of gigantic chest... probably full of gold.  And it\'s all ours!', 12, 0, 100, 0, 0, 0, '');
