INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(61636, 0, 0, 'Welcome to the Proving Grounds. Your first trial will now begin. Defeat each wave of illusions before time runs out.', 14, 0, 100, 0, 0, 38500, ''),
(61636, 1, 0, 'This Illusionary Slayer will test your ability to damage your opponent. Do not worry; it cannot harm you.', 14, 0, 100, 0, 0, 38492, ''),
(61636, 2, 0, 'A master of defense, the Illusionary Guardian deflects all attacks from the front. Stay behind it.', 14, 0, 100, 0, 0, 38494, ''),
(61636, 3, 0, 'Illusionary Varmints come in packs, and are harmless. Use attacks that affect multiple opponents to kill them quickly.', 14, 0, 100, 0, 0, 38498, ''),
(61636, 4, 0, 'Success! Hah, well done. See me for your next trial.', 14, 0, 100, 0, 0, 38554, ''),
(61636, 5, 0, 'As before, defeat each wave of illusions before time runs out. This time, you will encounter more difficult illusions.', 14, 0, 100, 0, 0, 38553, ''),
(61636, 6, 0, 'The Illusionary Amber-Weaver conjures globs of amber that float toward you and explode on any contact. Lead the amber globs into other illusions.', 14, 0, 100, 0, 0, 38497, ''),
(61636, 7, 0, 'The Illusionary Mystic will heal any ally that is significantly wounded. Interrupt its healing spells.', 14, 0, 100, 0, 0, 38495, ''),
(61636, 8, 0, 'Prepare yourself for the most difficult illusions. Defeat them before time expires, and success will be yours.', 14, 0, 100, 0, 0, 38552, ''),
(61636, 9, 0, 'Ah, the Illusionary Banana-Tosser! It will rapidly toss bananas toward you. Move to avoid them. Prevent it from running away from you, if you can.', 14, 0, 100, 0, 0, 38496, ''),
(61636, 10, 0, 'An Illusionary Banshee! Kill it, quickly, before it explodes!', 14, 0, 100, 0, 0, 38491, ''),
(61636, 11, 0, 'Oh, the Illusionary Sha! Save your strongest attacks for when its barrier falls, leaving it exposed.', 14, 0, 100, 0, 0, 38493, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(71828, 0, 0, 'Greetings. I am Sikari, master of jade lightning, chi, and healing mists. For this trial, you must protect me from the incoming illusions, while I heal you and dispatch our foes.', 14, 0, 100, 0, 0, 38439, ''),
(71828, 1, 0, 'Illusionary Rippers approaching. They should pose little challenge; they are but mindless grunts.', 14, 0, 100, 0, 0, 38428, ''),
(71828, 2, 0, 'Illusionary Foragers are attacking. Do not let their cute faces fool you. They can work together to cause terrible devastation.', 14, 0, 100, 0, 0, 38433, ''),
(71828, 3, 0, 'Greetings, again. Our next trial will be more challenging. Prepare to defend me.', 14, 0, 100, 0, 0, 38438, ''),
(71828, 4, 0, 'A new enemy, Illusionary Flamecallers. They cast fireballs and spew lava. Use the lava to your advantage; it will burn the other illusions.', 14, 0, 100, 0, 0, 38430, ''),
(71828, 5, 0, 'Beware! Illusionary Wind-Guards can use their wings to knock you back. When they do, they will likely switch to attacking me instead.', 14, 0, 100, 0, 0, 38431, ''),
(71828, 6, 0, 'Once again, you must defend me. Rotun, give us a challenge this time.', 14, 0, 100, 0, 0, 38437, ''),
(71828, 7, 0, 'Illusionary Ambushers! Get their attention, quick. And get them away from me, so they cannot hit me with their devastating bananas!', 14, 0, 100, 0, 0, 38432, ''),
(71828, 8, 0, 'Prepare your defenses. That is an Illusionary Conqueror! When they become enraged, they gain great strength, and nothing can stop them.', 14, 0, 100, 0, 0, 38429, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(72218, 0, 0, 'Hello. For this trial, you must keep us alive while we face the incoming illusions. I am Oto, and will protect you.', 14, 0, 100, 0, 0, 38599, ''),
(72218, 1, 0, 'Illusionary Hive-Singers! Their sonic waves will harm us all.', 14, 0, 100, 0, 0, 38596, ''),
(72218, 2, 0, 'I am a wall of iron, but I cannot hold much longer!', 14, 0, 100, 0, 0, 38594, ''),
(72218, 3, 0, 'Ah, a new challenge, Illusionary Conquerors! When they become enraged, they strike with incredible power.', 14, 0, 100, 0, 0, 38597, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(72219, 0, 0, 'Ah, our first enemy! Illusionary Rippers are but simple warriors. Now, let us do this!', 14, 0, 100, 0, 0, 38584, ''),
(72219, 1, 0, 'Illusionary Flamecallers! Watch your feet, everyone. Do not stand in the lava.', 14, 0, 100, 0, 0, 38585, ''),
(72219, 2, 0, 'The illusions will not hold back, this time. Their attacks will be relentless. Be prepared to use your strongest healing spells.', 14, 0, 100, 0, 0, 38588, ''),
(72219, 3, 0, '|cFFFF8040Ki the Assassin |r|cFF71D5FF|Hspell:145427|h[Kick]|h|r|cFFFF8040s the $n.|r', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(72220, 0, 0, 'Hah ha! Wonderful job, everyone! Friend, see Rotun about beginning the next trial.', 14, 0, 100, 0, 0, 38970, ''),
(72220, 1, 0, 'Ahh, Illusionary Tunnelers! Speedy and I have faced these foes before. Beware, they may burrow into the ground and then suddenly pop up under a new target, and CHOMP! Hah ha hah ha.', 14, 0, 100, 0, 0, 38967, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(72221, 0, 0, 'Hello again. More illusions approach, and we will require your healing arts.', 14, 0, 100, 0, 0, 38963, ''),
(72221, 1, 0, 'These Illusionary Aqualytes will affect us with dark magic. Dispel it quickly.', 14, 0, 100, 0, 0, 38961, ''),
(72221, 2, 0, '|cFFFF8040Kavan the Arcanist |r|cFF71D5FF|Hspell:145530|h[Counterspell]|h|r|cFFFF8040s the $n.|r', 41, 0, 100, 0, 0, 0, '');
