INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(72916, 0, 0, 'Wow, I have quite an appetite today!', 12, 0, 100, 0, 0, 0, ''),
(72916, 1, 0, 'I heard they discovered the lost secret of the Lin family\'s secret ingredient noodle soup.', 12, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(73316, 0, 0, 'Welcome, $n. I\'ve had the market area cleared to make room for Halfhill\'s first noodle stand, run by you!', 12, 0, 100, 3, 0, 0, ''),
(73316, 1, 0, 'Customers will line up and wait for you to tell them to sit down. They will only wait for a short while before leaving so be sure to get them to a seat before they leave.', 12, 0, 100, 0, 0, 0, ''),
(73316, 2, 0, 'Click on a patron who is waiting in line. You should see them wave to you when you have successfully interacted with them.', 12, 0, 100, 0, 0, 0, ''),
(73316, 3, 0, 'When a customer has been selected, click on an open seat and the customer will go sit there.', 12, 0, 100, 0, 0, 0, ''),
(73316, 4, 0, 'Once seated, a customer will wait a short while for you to deliver their noodle soup. As with waiting in line, be sure to get the customer their food before they decide to leave.', 12, 0, 100, 0, 0, 0, ''),
(73316, 5, 0, 'Make some noodle soup for your customer. This is a scholar so they like the simplicity of a standard noodle soup. Try making one now.', 12, 0, 100, 0, 0, 0, ''),
(73316, 6, 0, 'Now that the soup is made, pick it up by clicking on it. Soups will go bad if left out too long so only make what you need for your customers.', 12, 0, 100, 0, 0, 0, ''),
(73316, 7, 0, 'Excellent! Now your customer will happily eat the noodle soup you\'ve made for them. When they\'re done they\'ll leave happy.', 12, 0, 100, 4, 0, 0, ''),
(73316, 8, 0, 'Some tips: You can always tell what a customer wants by their outfit.', 12, 0, 100, 0, 0, 0, ''),
(73316, 9, 0, 'Some customers are hungry, they\'ll want a second bowl after they finish their first.', 12, 0, 100, 0, 0, 0, ''),
(73316, 10, 0, 'Other customers are impatient, they won\'t wait as long; but are really happy when they are served quickly.', 12, 0, 100, 0, 0, 0, ''),
(73316, 11, 0, 'Now get out there and make some noodle soup!', 12, 0, 100, 0, 0, 0, ''),
(73316, 12, 0, 'Well done!', 12, 0, 100, 4, 0, 0, '');
